use std::env;
use std::fs;
use std::process;

struct Entry {
    key: String,
    value: String,
}

fn fail(message: impl AsRef<str>) -> ! {
    eprintln!("{}", message.as_ref());
    process::exit(1);
}

fn main() {
    let mut arguments = env::args();
    arguments.next();
    let path = match arguments.next() {
        Some(path) => path,
        None => fail("missing input path"),
    };
    if arguments.next().is_some() {
        fail("unexpected extra argument");
    }

    let input = match fs::read_to_string(&path) {
        Ok(input) => input,
        Err(error) => fail(format!("cannot read {}: {}", path, error)),
    };

    let mut entries: Vec<Entry> = Vec::new();
    for (index, line) in input.lines().enumerate() {
        if line.is_empty() {
            fail(format!("malformed record on line {}", index + 1));
        }
        let fields: Vec<&str> = line.split('|').collect();
        if fields.len() != 3 {
            fail(format!("malformed record on line {}", index + 1));
        }
        let kind = fields[0];
        let key = fields[1];
        let value = fields[2];
        if key.is_empty() {
            fail(format!("empty key on line {}", index + 1));
        }

        match kind {
            "put" => {
                if let Some(entry) = entries.iter_mut().find(|entry| entry.key == key) {
                    entry.value.clear();
                    entry.value.push_str(value);
                } else {
                    entries.push(Entry {
                        key: key.to_owned(),
                        value: value.to_owned(),
                    });
                }
            }
            "delete" => {
                if !value.is_empty() {
                    fail(format!("malformed delete on line {}", index + 1));
                }
                if let Some(position) = entries.iter().position(|entry| entry.key == key) {
                    entries.remove(position);
                }
            }
            _ => fail(format!(
                "unknown record kind {:?} on line {}",
                kind,
                index + 1
            )),
        }
    }

    let mut output = String::new();
    for entry in entries {
        output.push_str(&entry.key);
        output.push('=');
        output.push_str(&entry.value);
        output.push('\n');
    }
    print!("{}", output);
}
